#include <stdio.h>

int global;          // 声明全局变量，若不初始化则自动为0

int main() {
    int a;           // 声明局部变量a（未初始化，值不可预测）
    int b = 10;      // 声明并初始化b为10
    int c = a + b;   // 危险：a是垃圾值，结果不可控
    printf("%d\n", c); // 输出可能是随机数

    int d = 0;       // 正确做法：声明时初始化
    printf("%d\n", d); // 输出0
    return 0;
}
```
